      "rank": 2,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Peter W. Shor",
        "Andrew M. Steane"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction supplied the essential physical logic for preserving quantum information despite decoherence and transformed quantum computing from a fragile ideal into a principled possibility.",
        "attribution": "Shor, Steane, and Kitaev made distinct foundational contributions to codes and fault-tolerant, topological approaches; the achievement is intrinsically distributed.",
        "maturity": "The framework is theoretically secure and experimental demonstrations of error-correction primitives are increasingly compelling.",
        "uncertainties": [
          "Large-scale fault-tolerant quantum computation has not yet been achieved.",
          "Attribution across the broad error-correction field is difficult to compress into three names."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B018",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Their theoretical work established trapped ions as an exceptionally clean route to quantum computation and quantum simulation, opening a major experimental field.",
        "attribution": "Cirac and Zoller are the clear central pair for the seminal trapped-ion quantum-computing proposal and its broader intellectual programme.",
        "maturity": "Trapped-ion processors and simulators have tested and extended the underlying ideas over decades in many laboratories.",
        "uncertainties": [
          "The precise division between recognition of the theoretical proposal and later experimental realization should be assessed."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks created an extraordinary precision-measurement capability and a controlled quantum system with consequences for metrology and fundamental tests.",
        "attribution": "Katori introduced the magic-wavelength lattice-clock concept, while Ye made defining experimental advances; the pairing is persuasive.",
        "maturity": "Performance, reproducibility, and scientific uses have been established over a long period across international laboratories.",
        "uncertainties": [
          "The relative credit of other important clock pioneers merits detailed historical examination."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Mikhail D. Lukin",
        "Antoine Browaeys",
        "Mark Saffman"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade enabled programmable many-atom systems in which strong interactions and quantum dynamics can be engineered with remarkable directness.",
        "attribution": "Lukin, Browaeys, Saffman, and Grangier all have substantial claims spanning conceptual and experimental development; the proposed attribution is necessarily selective.",
        "maturity": "Neutral-atom arrays are now mature experimental platforms with repeated demonstrations of blockade, simulation, and programmable control.",
        "uncertainties": [
          "Rapid technological development makes it important to distinguish the original discovery from later platform advances.",
          "Attribution is broader than the three-person Nobel limit."
        ]
      }
    },
    {
      "rank": 6,
